&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-scheme-color=&quot;@000000,1,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Plataforma e Experiência: &lt;/span&gt;&lt;/strong&gt;&lt;span data-scheme-color=&quot;@000000,1,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;construção de jornadas digitais fluídas e plataformas internas que habilitam escala, consistência e eficiente para clientes, assessores e &lt;/span&gt;&lt;span data-scheme-color=&quot;@000000,1,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;colaboradores. &lt;/span&gt;&lt;/li&gt;
